function applyUiLanguage() {
  const english=state.language==='en-US'; const reverse=Object.fromEntries(Object.entries(EN_TRANSLATIONS).map(([a,b])=>[b,a])); const dict=english?EN_TRANSLATIONS:reverse;
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT); let node;
  while(node=walker.nextNode()){if(['SCRIPT','STYLE'].includes(node.parentElement?.tagName))continue;const raw=node.nodeValue;const trimmed=raw.trim();if(dict[trimmed])node.nodeValue=raw.replace(trimmed,dict[trimmed]);}
  document.querySelectorAll('[placeholder]').forEach(el=>{const src=el.getAttribute('placeholder');if(english&&PLACEHOLDER_EN[src])el.setAttribute('placeholder',PLACEHOLDER_EN[src]);else if(!english){const rev=Object.fromEntries(Object.entries(PLACEHOLDER_EN).map(([a,b])=>[b,a]));if(rev[src])el.setAttribute('placeholder',rev[src]);}});
  document.documentElement.lang=english?'en':'zh-Hant';
}
function ui(zh,en){return state.language==='en-US'?en:zh;}
function responseLanguageRule(){return state.language==='en-US'?'IMPORTANT: Write every question, comment, label, and feedback field in English only. Do not use Chinese.':'所有題目、評論與回饋欄位都必須使用繁體中文。';}
function updateTodayLabel(){const locale=state.language==='en-US'?'en-US':'zh-TW';const dateText=new Intl.DateTimeFormat(locale,{month:'long',day:'numeric',weekday:'long'}).format(new Date());$('#todayLabel').textContent=`${dateText} · TODAY'S PRACTICE`;}

function analysisButtonLabel(){return state.practiceMode==='manuscript'?ui('分析我的講稿 ✦','Analyze my manuscript ✦'):ui('分析我的回答 ✦','Analyze my answer ✦');}
function setPracticeMode(mode){
  const previousMode=state.practiceMode;
  if(previousMode==='question')state.modeDrafts.question={topic:state.topic,questions:[...state.questions],index:state.index,text:$('#transcript').value};
  else state.modeDrafts.manuscript.text=$('#transcript').value;
  state.practiceMode=mode==='manuscript'?'manuscript':'question';
  const manuscript=state.practiceMode==='manuscript';
  resetRecorderForQuestion();
  $('#feedbackPanel').classList.add('hidden');
  $('#questionModeButton').classList.toggle('active',!manuscript);
  $('#manuscriptModeButton').classList.toggle('active',manuscript);
  $('#topicPanel').classList.toggle('hidden',manuscript);
  $('#practicePanel').classList.toggle('manuscript-mode',manuscript);
  const questionDraft=state.modeDrafts.question;
  const hasQuestion=!manuscript&&questionDraft.questions.length>0;
  $('#practicePanel').classList.toggle('hidden',!manuscript&&!hasQuestion);
  $('#practicePanel .section-heading h2').textContent=manuscript?ui('開始自由講稿','Start your manuscript'):ui('開始即興回答','Start your impromptu answer');
  const transcriptLabel=$('.transcript-wrap label');
  transcriptLabel.childNodes[0].nodeValue=manuscript?ui('講稿內容 ','Manuscript '):ui('你的回答 ','Your answer ');
  transcriptLabel.querySelector('span').textContent=manuscript?ui('可直接錄音或輸入文字','Record or type directly'):ui('可直接修改逐字稿','You can edit the transcript');
  $('#transcript').placeholder=manuscript?ui('直接錄音或在這裡輸入講稿內容⋯','Record or type your manuscript here…'):ui('錄音後逐字稿會出現在這裡，也可以直接輸入你的回答⋯','Your transcript will appear here, or you can type your answer.');
  $('#analyzeButton').textContent=analysisButtonLabel();
  $('#nextButton').classList.toggle('hidden',manuscript);
  $('#retryButton').textContent=manuscript?ui('重新開始','Start over'):ui('再答一次','Try again');
  if(manuscript){state.topic=ui('自由講稿','Free manuscript');state.questions=[ui('自由講稿內容','Free manuscript')];state.index=0;$('#transcript').value=state.modeDrafts.manuscript.text;requestAnimationFrame(()=>$('#transcript').focus());}
  else {state.topic=questionDraft.topic;state.questions=[...questionDraft.questions];state.index=Math.min(questionDraft.index,Math.max(0,state.questions.length-1));$('#topicInput').value=state.topic;$('#transcript').value=questionDraft.text;if(hasQuestion){$('#questionText').textContent=state.questions[state.index];$('#topicBadge').textContent=state.topic;$('#questionIndex').textContent=state.language==='en-US'?`Question ${state.index+1} of ${state.questions.length}`:`第 ${state.index+1} / ${state.questions.length} 題`;}}
  updateCharCount();
  applyUiLanguage();
}

