async function importBackupFile(file){
  try{const payload=JSON.parse(await file.text());if(payload?.format!=='table-topics-practice-backup'||!payload.data||!Array.isArray(payload.data.practice?.history)||!Array.isArray(payload.data.aiSettings?.projects))throw new Error(ui('不是有效的 Table Topics 備份檔','This is not a valid Table Topics backup file'));const count=payload.data.practice.history.length;const hasKeys=payload.data.aiSettings.projects.some(project=>project.apiKey);if(!confirm(ui(`確定匯入 ${count} 筆練習資料並取代目前所有資料嗎？${hasKeys?' 此檔案包含 API Key。':''}`,`Import ${count} practices and replace all current data?${hasKeys?' This file contains API keys.':''}`)))return;localStorage.setItem(CONFIG.storageKey,JSON.stringify(payload.data.practice));localStorage.setItem(AI_CONFIG_KEY,JSON.stringify(payload.data.aiSettings));if(CONFIG.languages[payload.data.language])localStorage.setItem(UI_LANGUAGE_KEY,payload.data.language);const cloudUpdated=await window.tableTopicsCloud?.replaceData?.(payload.data.practice);if(cloudUpdated===false){toast(ui('資料已匯入本機，但雲端更新失敗；請保持此頁開啟並重試','Imported locally, but cloud update failed. Keep this page open and try again.'));return;}toast(ui(window.tableTopicsCloud?.isEnabled?.()?'匯入完成，雲端資料已更新':'匯入完成，正在重新載入',window.tableTopicsCloud?.isEnabled?.()?'Import complete. Cloud data updated.':'Import complete. Reloading…'));setTimeout(()=>location.reload(),700);}catch(error){toast(`${ui('匯入失敗','Import failed')}: ${error.message}`);}finally{$('#importBackupInput').value='';}
}
