async function testAgentConnection(){
  const btn=$('#testConnectionButton'),draft={name:$('#projectNameInput').value,provider:$('#providerSelect').value,model:selectedModel(),endpoint:$('#endpointInput').value.trim(),apiKey:$('#apiKeyInput').value.trim(),prompt:$('#promptInput').value,inputTokenRate:Math.max(0,Number($('#costInputRate').value)||0),outputTokenRate:Math.max(0,Number($('#costOutputRate').value)||0)};
  if(draft.provider==='builtin'){setConnectionTestStatus('success',ui('內建教練可以使用','Built-in coach is ready'),ui('內建模式不需要 API Key 或網路連線。','Built-in mode does not require an API key or network connection.'));return;}
  const missing=[!draft.apiKey&&'API Key',!draft.endpoint&&'Endpoint',!draft.model&&ui('模型','Model')].filter(Boolean);
  if(missing.length){setConnectionTestStatus('error',ui('設定尚未完成','Configuration is incomplete'),ui(`請先填寫：${missing.join('、')}`,`Please provide: ${missing.join(', ')}`));return;}
  btn.disabled=true;btn.textContent=ui('測試中⋯','Testing…');setConnectionTestStatus('testing',ui('正在測試 API 連線…','Testing API connection…'),ui('正在驗證 Endpoint、模型與 API Key，最多等待 20 秒。','Checking the endpoint, model, and API key. This can take up to 20 seconds.'));
  const startedAt=Date.now();
  try{await Promise.race([callAgent('Reply with only OK.',draft),new Promise((_,reject)=>setTimeout(()=>reject(new Error(ui('連線逾時（20 秒）','Connection timed out after 20 seconds'))),20000))]);const seconds=((Date.now()-startedAt)/1000).toFixed(1);setConnectionTestStatus('success',ui('API 連線成功','API connection successful'),ui(`API Key、Endpoint 與模型均可使用，回應時間 ${seconds} 秒。`,`The API key, endpoint, and model are working. Response time: ${seconds}s.`));}
  catch(error){setConnectionTestStatus('error',ui('API 連線失敗','API connection failed'),error.message||ui('發生未知錯誤，請檢查設定。','An unknown error occurred. Check your settings.'));}
  finally{btn.disabled=false;btn.textContent=ui('測試連線','Test connection');}
}
